<script setup lang="ts">
import{onMounted,ref}from'vue';import{MediaRecorderAdapter}from'../adapters/media-recorder.adapter';import{WebAudioAnalyzerAdapter}from'../adapters/web-audio-analyzer.adapter';import{WebAudioCropperAdapter}from'../adapters/web-audio-cropper.adapter';import{WebAudioComposerAdapter}from'../adapters/web-audio-composer.adapter';import{IndexedDbMaterialRepository}from'../adapters/indexeddb-material.repository';import{IndexedDbDraftStore}from'../adapters/indexeddb-draft.store';import{CanvasCoverRendererAdapter}from'../adapters/canvas-cover-renderer.adapter';import{IndexedDbMemeRepository}from'../adapters/indexeddb-meme.repository';import{BrowserShareAdapter}from'../adapters/browser-share.adapter';import{useStudio,type StudioDependencies}from'./useStudio';import RecorderPanel from'./components/RecorderPanel.vue';import ArrangeBoard from'./components/ArrangeBoard.vue';import EmotionPanel from'./components/EmotionPanel.vue';import CoverWorkshop from'./components/CoverWorkshop.vue';import MemeGallery from'./components/MemeGallery.vue';import SharePanel from'./components/SharePanel.vue';
const props=defineProps<{dependencies?:StudioDependencies}>();const defaults:StudioDependencies={recorder:new MediaRecorderAdapter(),analyzer:new WebAudioAnalyzerAdapter(),cropper:new WebAudioCropperAdapter(),composer:new WebAudioComposerAdapter(),materials:new IndexedDbMaterialRepository(),drafts:new IndexedDbDraftStore(),renderer:new CanvasCoverRendererAdapter(),repository:new IndexedDbMemeRepository(),share:new BrowserShareAdapter()};const studio=useStudio(props.dependencies??defaults);const recording=ref(false);async function start(){await studio.startRecording();recording.value=!studio.error.value}async function stop(){await studio.stopRecording();recording.value=false}onMounted(()=>{studio.loadCollection();studio.restoreWorkspace()});
</script>
<template><div class="sound-app"><header><div class="logo">声<span>!</span></div><div><small>SOUND REACTION STUDIO / 005</small><h1>声音表情包工坊</h1></div><nav><button v-for="(s,i) in ['录音','编排','情绪','封面','作品集']" :key="s" :class="{active:['record','arrange','emotion','cover','collection'][i]===studio.stage.value}">{{ i+1 }} {{ s }}</button></nav></header><main><section class="intro"><div><span class="kicker">MAKE SOME NOISE. MAKE IT YOURS.</span><h2>让声音，<em>长出表情。</em></h2><p>录几段、排一排、认情绪、做封面。十秒就能生成一张会发声的表情包。</p></div><div class="intro-badge"><b>10</b><span>SECONDS<br>OF ATTITUDE</span></div></section><div v-if="studio.error.value" class="error-banner">{{studio.error.value}}</div><div v-if="studio.notice.value" class="notice-banner">{{studio.notice.value}}</div><RecorderPanel v-if="studio.stage.value==='record'" :recording="recording" :level="studio.level.value" @record="start" @stop="stop" @import="studio.importAudio($event,$event.name)"/><ArrangeBoard v-else-if="studio.stage.value==='arrange'" :materials="studio.materials.value" :items="studio.items.value" :total="studio.totalDuration.value" :problem="studio.arrangementError.value" :processing="studio.processing.value" :pending-delete="studio.pendingDelete.value" :preview-blob="studio.previewBlob.value" :preview-key="studio.previewKey.value" @add-clip="studio.addClip" @delete-material="studio.requestDeleteMaterial" @confirm-delete="studio.confirmDeleteMaterial" @patch-item="studio.patchItem" @move-item="studio.moveItem" @remove-item="studio.removeItem" @insert-silence="studio.insertSilence" @import="studio.importAudio($event,$event.name)" @to-record="studio.backToRecord" @preview="studio.preview" @compose="studio.composeAndAnalyze"/><EmotionPanel v-else-if="studio.stage.value==='emotion'&&studio.emotion.value" :result="studio.emotion.value" @select="studio.selectEmotion" @next="studio.goCover"/><CoverWorkshop v-else-if="studio.stage.value==='cover'" :config="studio.cover.value" :title="studio.draft.title" @patch="studio.cover.value={...studio.cover.value,...$event}" @title="studio.draft.title=$event" @save="studio.save()"/><MemeGallery v-else :items="studio.collection.value" @edit="studio.editMeme" @remove="studio.deleteMeme" @share="studio.shareMeme" @new="studio.newRecording"/><SharePanel/></main></div></template>
